//! Native MMR oracle for the cross-target conformance test; stdin/stdout JSON.
use arkhe_verify_core::mmr::{verify_proof, ProofStep};
use serde::Deserialize;
use serde_json::json;
use std::io::{self, Read};

#[derive(Deserialize)]
struct Case {
    id: String,
    leaf_hex: String,
    leaf_count: usize,
    proof: Vec<ProofStep>,
    root_hex: String,
}

#[derive(Deserialize)]
struct Input {
    cases: Vec<Case>,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;
    let input: Input = serde_json::from_str(&input)?;
    let mut results = Vec::new();
    for case in input.cases {
        let leaf = hex::decode(case.leaf_hex)?;
        let root: [u8; 32] = hex::decode(case.root_hex)?
            .try_into()
            .map_err(|_| "root must have 32 bytes")?;
        let accepted = verify_proof(&leaf, case.leaf_count, &case.proof, &root).unwrap_or(false);
        results.push(json!({ "id": case.id, "accepted": accepted }));
    }
    println!("{}", json!({ "results": results }));
    Ok(())
}

//! Bounded local mandate profile, not an AP2 credential verifier or a payment rail.
use crate::{
    cbor::canonical::encode_json,
    mmr::{verify_proof_at, ProofStep},
};
use arkhe_core::{
    work::{WorkIntent, WorkIntentType},
    Digest32,
};
use ed25519_dalek::{Signature, VerifyingKey};
use serde::{Deserialize, Serialize};

pub const PROFILE: &str = "arkhe-action-mandate@1";

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Mandate {
    pub profile: String,
    pub requested_by: String,
    pub intent_type: WorkIntentType,
    pub operation_id: Digest32,
    pub target: Digest32,
    pub policy_digest: Digest32,
    /// Finite exact parameter commitments; no inferred natural-language scope.
    pub allowed_parameters: Vec<Digest32>,
    pub issued_at: i64,
    pub expires_at: i64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Checkpoint {
    pub profile_digest: String,
    pub root: [u8; 32],
    pub leaf_count: u32,
    pub issued_at: i64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ActionProof {
    pub mandate: Mandate,
    pub mandate_signature: Vec<u8>,
    pub checkpoint: Checkpoint,
    pub checkpoint_signature: Vec<u8>,
    pub leaf_index: u32,
    pub steps: Vec<ProofStep>,
}

/// Host-configured keys, policy, clock and retained checkpoint. Never trust these
/// merely because they appear next to a proof. Log time is a trusted attestation,
/// not a timestamp independently derived from MMR inclusion.
pub struct Trust {
    pub mandate_key: VerifyingKey,
    pub log_key: VerifyingKey,
    pub policy_digest: Digest32,
    pub checkpoint: Checkpoint,
    pub now: i64,
    pub max_checkpoint_age: i64,
}

fn bytes(domain: &[u8], value: &impl Serialize) -> Result<Vec<u8>, &'static str> {
    let value = serde_json::to_value(value).map_err(|_| "invalid mandate projection")?;
    let mut out = domain.to_vec();
    out.extend(encode_json(&value).map_err(|_| "invalid canonical mandate")?);
    Ok(out)
}
pub fn mandate_bytes(m: &Mandate) -> Result<Vec<u8>, &'static str> {
    bytes(b"AKG:ACTION:MANDATE:v1\0", m)
}
pub fn checkpoint_bytes(c: &Checkpoint) -> Result<Vec<u8>, &'static str> {
    bytes(b"AKG:ACTION:CHECKPOINT:v1\0", c)
}
fn check_signature(
    key: &VerifyingKey,
    payload: &[u8],
    signature: &[u8],
) -> Result<(), &'static str> {
    let signature = Signature::from_slice(signature).map_err(|_| "invalid signature length")?;
    key.verify_strict(payload, &signature)
        .map_err(|_| "invalid signature")
}

/// Checks a mandate before dispatch. Does not establish observed execution or
/// spend/replay state; the broker must reserve that state before invoking a rail.
pub fn verify(
    proof: &ActionProof,
    intent: &WorkIntent,
    trust: &Trust,
) -> Result<Digest32, &'static str> {
    let m = &proof.mandate;
    let c = &proof.checkpoint;
    if m.profile != PROFILE
        || c.profile_digest != crate::mmr::profile::PROFILE_DIGEST_HEX
        || m.requested_by != intent.requested_by
        || m.intent_type != intent.intent_type
        || m.operation_id != intent.operation_id()
        || m.target != intent.target
        || m.policy_digest == Digest32::ZERO
        || m.policy_digest != trust.policy_digest
        || m.allowed_parameters.is_empty()
        || m.allowed_parameters.len() > 256
        || !m.allowed_parameters.contains(&intent.parameters_digest)
    {
        return Err("mandate does not bind this action and policy");
    }
    let mut unique = std::collections::HashSet::new();
    if !m.allowed_parameters.iter().all(|p| unique.insert(*p)) {
        return Err("duplicate parameter commitment");
    }
    if trust.now < 0
        || trust.max_checkpoint_age < 0
        || m.issued_at < 0
        || m.issued_at > c.issued_at
        || c.issued_at >= trust.now
        || m.expires_at <= trust.now
        || trust
            .now
            .checked_sub(c.issued_at)
            .is_none_or(|age| age > trust.max_checkpoint_age)
        || checkpoint_bytes(c)? != checkpoint_bytes(&trust.checkpoint)?
    {
        return Err("mandate or checkpoint time/trust mismatch");
    }
    let payload = mandate_bytes(m)?;
    check_signature(&trust.mandate_key, &payload, &proof.mandate_signature)?;
    check_signature(
        &trust.log_key,
        &checkpoint_bytes(c)?,
        &proof.checkpoint_signature,
    )?;
    if !verify_proof_at(
        &payload,
        c.leaf_count as usize,
        proof.leaf_index as usize,
        &proof.steps,
        &c.root,
    )
    .map_err(|_| "invalid mandate inclusion proof")?
    {
        return Err("mandate absent from trusted checkpoint");
    }
    Ok(Digest32::blake3(b"AKG:ACTION:VERIFIED:v1\0", &payload))
}

use crate::{cbor::canonical::encode_json, error::VerifyError};
use serde_json::Value;

const REQUIRED: &[&str] = &[
    "instanceID",
    "claim_generator_info",
    "signature",
    "created_assertions",
];

pub fn canonicalize_claim_v2(claim: &Value) -> Result<Vec<u8>, VerifyError> {
    let obj = claim
        .as_object()
        .ok_or_else(|| VerifyError::InvalidInput("C2PA claim must be a map".into()))?;

    for field in REQUIRED {
        if !obj.contains_key(*field) {
            return Err(VerifyError::InvalidInput(format!(
                "missing C2PA field {field}"
            )));
        }
    }

    if obj.get("alg").and_then(Value::as_str) == Some("Ed25519") {
        return Err(VerifyError::InvalidInput(
            "C2PA claim alg is a hash algorithm, not Ed25519".into(),
        ));
    }

    encode_json(claim)
}

use crate::c2pa::claim::canonicalize_claim_v2;
use crate::cbor::canonical::encode_json;
use crate::error::VerifyError;
use crate::hash::blake3_256;
use ed25519_dalek::{Signature, VerifyingKey};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

pub const PROFILE: &str = "arkhe-c2pa-claim-signature-v1";
pub const DOMAIN: &[u8] = b"AKG:C2PA-CLAIM-SIG:v1\0";

#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Signer {
    pub kid: String,
    pub issuer: String,
    pub alg: String,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Envelope {
    pub schema: u32,
    pub profile: String,
    pub claim: Value,
    pub signer: Signer,
    pub signature_hex: String,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct TrustRoot {
    pub kid: String,
    pub issuer: String,
    pub public_key_hex: String,
    pub status: String,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct TrustRoots {
    pub schema: u32,
    pub profile: String,
    pub roots: Vec<TrustRoot>,
}

#[derive(Debug, Clone, Serialize)]
pub struct SignatureVerification {
    pub schema: u32,
    pub profile: String,
    pub status: String,
    pub signature_verified: bool,
    pub signer_kid: Option<String>,
    pub signer_issuer: Option<String>,
    pub trust_root_status: String,
    pub claim_canonical_sha256: Option<String>,
    pub signed_payload_sha256: Option<String>,
    pub provenance_verification: String,
    pub c2pa_standard_validation: String,
    pub authority: bool,
    pub findings: Vec<String>,
}

fn parse_key(text: &str) -> Result<VerifyingKey, VerifyError> {
    let bytes = hex::decode(text)
        .map_err(|_| VerifyError::InvalidInput("trust root public key is not hex".into()))?;
    let bytes: [u8; 32] = bytes
        .try_into()
        .map_err(|_| VerifyError::InvalidInput("trust root public key must be 32 bytes".into()))?;
    VerifyingKey::from_bytes(&bytes)
        .map_err(|_| VerifyError::InvalidInput("trust root public key is invalid".into()))
}

pub fn signing_payload(
    claim: &Value,
    kid: &str,
    issuer: &str,
    alg: &str,
) -> Result<Vec<u8>, VerifyError> {
    if kid.is_empty() || issuer.is_empty() || kid.len() > 256 || issuer.len() > 256 {
        return Err(VerifyError::InvalidInput(
            "signer kid/issuer must be non-empty and at most 256 bytes".into(),
        ));
    }
    let canonical = canonicalize_claim_v2(claim)?;
    let digest = hex::encode(blake3_256(&canonical));
    let message = json!({
        "profile": PROFILE,
        "kid": kid,
        "issuer": issuer,
        "alg": alg,
        "claim_sha256": digest,
    });
    let encoded = encode_json(&message)?;
    let mut payload = Vec::with_capacity(DOMAIN.len() + encoded.len());
    payload.extend_from_slice(DOMAIN);
    payload.extend_from_slice(&encoded);
    Ok(payload)
}

fn rejected(
    status: &str,
    trust_root_status: &str,
    envelope: Option<&Envelope>,
    claim_digest: Option<String>,
    payload_digest: Option<String>,
    findings: Vec<String>,
) -> SignatureVerification {
    SignatureVerification {
        schema: 1,
        profile: PROFILE.into(),
        status: status.into(),
        signature_verified: false,
        signer_kid: envelope.map(|e| e.signer.kid.clone()),
        signer_issuer: envelope.map(|e| e.signer.issuer.clone()),
        trust_root_status: trust_root_status.into(),
        claim_canonical_sha256: claim_digest,
        signed_payload_sha256: payload_digest,
        provenance_verification: "NOT_PERFORMED".into(),
        c2pa_standard_validation: "NOT_PERFORMED".into(),
        authority: false,
        findings,
    }
}

pub fn verify(
    envelope_json: &str,
    trust_roots_json: &str,
) -> Result<SignatureVerification, VerifyError> {
    let envelope: Envelope = serde_json::from_str(envelope_json)
        .map_err(|_| VerifyError::InvalidInput("signature envelope is malformed".into()))?;
    let roots: TrustRoots = serde_json::from_str(trust_roots_json)
        .map_err(|_| VerifyError::InvalidInput("trust roots are malformed".into()))?;

    if envelope.schema != 1 || roots.schema != 1 {
        return Err(VerifyError::InvalidInput(
            "signature envelope and trust roots require schema 1".into(),
        ));
    }
    if envelope.profile != PROFILE || roots.profile != PROFILE {
        return Err(VerifyError::Unsupported(format!(
            "signature profile must be {PROFILE}"
        )));
    }

    let canonical = canonicalize_claim_v2(&envelope.claim)?;
    let claim_digest = hex::encode(blake3_256(&canonical));
    let payload = signing_payload(
        &envelope.claim,
        &envelope.signer.kid,
        &envelope.signer.issuer,
        &envelope.signer.alg,
    )?;
    let payload_digest = hex::encode(blake3_256(&payload));

    if envelope.signer.alg != "Ed25519" {
        return Ok(rejected(
            "SIGNATURE_UNSUPPORTED",
            "NOT_EVALUATED",
            Some(&envelope),
            Some(claim_digest),
            Some(payload_digest),
            vec!["only the Ed25519 signature algorithm is implemented".into()],
        ));
    }

    let mut seen = std::collections::BTreeSet::new();
    for root in &roots.roots {
        if !seen.insert((root.kid.clone(), root.issuer.clone())) {
            return Err(VerifyError::InvalidInput(
                "trust roots contain a duplicate kid/issuer".into(),
            ));
        }
        if root.issuer.is_empty() || root.kid.is_empty() {
            return Err(VerifyError::InvalidInput(
                "trust root kid/issuer must be non-empty".into(),
            ));
        }
    }

    let root = roots
        .roots
        .iter()
        .find(|root| root.kid == envelope.signer.kid && root.issuer == envelope.signer.issuer);
    let Some(root) = root else {
        return Ok(rejected(
            "TRUST_ROOT_REJECTED",
            "MISSING",
            Some(&envelope),
            Some(claim_digest),
            Some(payload_digest),
            vec!["signer is not present in the supplied trust roots".into()],
        ));
    };
    if root.status != "active" {
        return Ok(rejected(
            "TRUST_ROOT_REJECTED",
            "REVOKED",
            Some(&envelope),
            Some(claim_digest),
            Some(payload_digest),
            vec![format!("trust root status is {}", root.status)],
        ));
    }

    let key = parse_key(&root.public_key_hex)?;
    let signature_bytes = hex::decode(&envelope.signature_hex)
        .map_err(|_| VerifyError::InvalidInput("signature is not hex".into()))?;
    let signature_bytes: [u8; 64] = signature_bytes
        .try_into()
        .map_err(|_| VerifyError::InvalidInput("signature must be 64 bytes".into()))?;
    let signature = Signature::from_bytes(&signature_bytes);

    if key.verify_strict(&payload, &signature).is_err() {
        return Ok(rejected(
            "SIGNATURE_INVALID",
            "ACTIVE",
            Some(&envelope),
            Some(claim_digest),
            Some(payload_digest),
            vec!["Ed25519 signature does not verify over the Arkhe signing payload".into()],
        ));
    }

    Ok(SignatureVerification {
        schema: 1,
        profile: PROFILE.into(),
        status: "SIGNATURE_VALID".into(),
        signature_verified: true,
        signer_kid: Some(envelope.signer.kid),
        signer_issuer: Some(envelope.signer.issuer),
        trust_root_status: "ACTIVE".into(),
        claim_canonical_sha256: Some(claim_digest),
        signed_payload_sha256: Some(payload_digest),
        provenance_verification: "NOT_PERFORMED".into(),
        c2pa_standard_validation: "NOT_PERFORMED".into(),
        authority: false,
        findings: vec![
            "signature verified against a pinned Ed25519 trust root".into(),
            "trust root authenticity, revocation freshness and signer intent remain host obligations"
                .into(),
        ],
    })
}

use crate::error::VerifyError;
use serde_json::Value;

fn head(major: u8, n: u64, out: &mut Vec<u8>) {
    let base = major << 5;
    match n {
        0..=23 => out.push(base | n as u8),
        24..=0xff => out.extend_from_slice(&[base | 24, n as u8]),
        0x100..=0xffff => {
            out.push(base | 25);
            out.extend_from_slice(&(n as u16).to_be_bytes());
        }
        0x1_0000..=0xffff_ffff => {
            out.push(base | 26);
            out.extend_from_slice(&(n as u32).to_be_bytes());
        }
        _ => {
            out.push(base | 27);
            out.extend_from_slice(&n.to_be_bytes());
        }
    }
}

pub fn encode_json(v: &Value) -> Result<Vec<u8>, VerifyError> {
    let mut out = Vec::new();
    encode_into(v, &mut out)?;
    Ok(out)
}

fn encode_into(v: &Value, out: &mut Vec<u8>) -> Result<(), VerifyError> {
    match v {
        Value::Null => out.push(0xf6),
        Value::Bool(false) => out.push(0xf4),
        Value::Bool(true) => out.push(0xf5),
        Value::Number(n) => {
            if let Some(u) = n.as_u64() {
                head(0, u, out);
            } else if let Some(i) = n.as_i64() {
                if i >= 0 {
                    head(0, i as u64, out);
                } else {
                    head(1, (-1 - i) as u64, out);
                }
            } else {
                return Err(VerifyError::Unsupported(
                    "floating point is outside Phase-1 deterministic subset".into(),
                ));
            }
        }
        Value::String(s) => {
            let b = s.as_bytes();
            head(3, b.len() as u64, out);
            out.extend_from_slice(b);
        }
        Value::Array(a) => {
            head(4, a.len() as u64, out);
            for x in a {
                encode_into(x, out)?;
            }
        }
        Value::Object(m) => {
            let mut pairs = Vec::with_capacity(m.len());
            for (k, v) in m {
                let key = encode_json(&Value::String(k.clone()))?;
                let val = encode_json(v)?;
                pairs.push((key, val));
            }
            pairs.sort_by(|a, b| a.0.cmp(&b.0));
            head(5, pairs.len() as u64, out);
            for (k, v) in pairs {
                out.extend_from_slice(&k);
                out.extend_from_slice(&v);
            }
        }
    }
    Ok(())
}

pub const DOMAIN_VERIFY: &[u8] = b"AKG:VERIFY:v1\0";
pub const DOMAIN_ASSESS: &[u8] = b"AKG:ASSESS:v1\0";
pub const DOMAIN_BRANCH: &[u8] = b"AKG:BRANCH:v1\0";
pub const DOMAIN_MMR_PROFILE: &[u8] = b"AKG:MMRPROFILE:v1\0";

use crate::{cbor::canonical::encode_json, error::VerifyError};
use serde_json::Value;

pub fn canonicalize_metadata(metadata: &Value) -> Result<Vec<u8>, VerifyError> {
    match metadata {
        Value::Object(_) => encode_json(metadata),
        _ => Err(VerifyError::InvalidInput(
            "GGUF metadata must be a map".into(),
        )),
    }
}
